15:  * Fog of war (off by default, per-level flag). Terrain is always known — only
16:  * units are hidden — and a unit sitting in cover (`opaque` terrain) is spotted
17:  * only from an adjacent tile. Simple, readable, and enough to make scouting
18:  * matter for future modes.
19:  */
20: export function visibleTiles(rules: VisionRules, state: GameState, viewer: PlayerId): Set<number> {
21:   const content = rules.content;
22:   const seen = new Set<number>();
23:   const battlefield = new Battlefield(state, content);
24:   if (!state.rules.fog) {
25:     for (let i = 0; i < state.map.tiles.length; i++) seen.add(i);
26:     return seen;
27:   }
28:   for (const u of state.units) {
29:     if (!areAllies(state, u.owner, viewer) && u.owner !== viewer) continue;
30:     const def = content.units.get(u.type);
31:     const bonus = battlefield.cell(u).vision;
32:     for (const index of boardOf(rules, state).ringIndices({ x: u.x, y: u.y }, 0, def.vision + bonus)) {
33:       seen.add(index);
34:     }
35:   }
36:   for (let i = 0; i < state.map.owners.length; i++) {
37:     if (state.map.owners[i] === viewer) seen.add(i);
38:   }
39:   return seen;
40: }
