42: export function isUnitVisible(
43:   rules: VisionRules,
44:   state: GameState,
45:   viewer: PlayerId,
46:   u: Unit,
47:   seen?: Set<number>,
48: ): boolean {
49:   if (!state.rules.fog) return true;
50:   if (u.owner === viewer || areAllies(state, u.owner, viewer)) return true;
51:   const i = idx(state.map, u.x, u.y);
52:   const visible = seen ?? visibleTiles(rules, state, viewer);
53:   if (!visible.has(i)) return false;
54:   if (!new Battlefield(state, rules.content).cell(u).terrain.opaque) return true;
55:   // Hidden in cover unless something friendly is standing right next to it.
56:   const board = boardOf(rules, state);
57:   return state.units.some(
58:     (o) =>
59:       (o.owner === viewer || areAllies(state, o.owner, viewer)) &&
60:       board.distance({ x: o.x, y: o.y }, { x: u.x, y: u.y }) === 1,
61:   );

